mapper.delete:
DELETE FROM
	photo.photo_favorite

	 AND account_no = #{accountNo, typeHandler=com.web.gallery.type_handler.AccountNoTypeHandler}
	 AND favorite_photo_account_no = #{favoritePhotoAccountNo, typeHandler=com.web.gallery.type_handler.AccountNoTypeHandler}
	 AND favorite_photo_no = #{favoritePhotoNo, typeHandler=com.web.gallery.type_handler.PhotoNoTypeHandler}
